import React from 'react';

const Home = () => {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-4xl font-bold text-gray-900">Welcome to AI Product Description Generator</h1>
      <p className="text-gray-600 mt-4">Generate amazing product descriptions with AI</p>
    </div>
  );
};

export default Home;
